	local n1_2_1 = N("ImageLabel", { Name = "searchIcon", BorderSizePixel = 0, AnchorPoint = Vector2.new(0, 0), Position = UDim2.new(0, 12, 0, 10), Size = UDim2.new(0, 14, 0, 14), BackgroundTransparency = 1, Image = Build.IconAsset["search"] or "", ImageColor3 = Color3.fromRGB(165, 165, 182) }, n1_2)
