	local n1_2_2 = N("TextLabel", { Name = "searchText", BorderSizePixel = 0, AnchorPoint = Vector2.new(0, 0), Position = UDim2.new(0, 35, 0, 7.25), Size = UDim2.new(1, -127.34, 0, 19.5), BackgroundTransparency = 1, Text = "Search...", TextSize = 15, TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Center, FontFace = Build.Font, TextColor3 = Color3.fromRGB(165, 165, 182) }, n1_2)
	P["searchText"] = n1_2_2
