	local n1_3 = N("Frame", { Name = "tabs", BorderSizePixel = 0, AnchorPoint = Vector2.new(0, 0), Position = UDim2.new(0, 13, 0, 107), Size = UDim2.new(1, -26, 1, -120), BackgroundTransparency = 1 }, n1)
	P["tabs"] = n1_3
